{
  "format": "hui-bot",
  "version": 2,
  "bot": {
    "name": "Ada for",
    "title": "Pat's helper",
    "description": "Helps at.",
    "avatar": {
      "emoji": "🤖",
      "shape": "round",
      "color": "#336699"
    },
    "model": "claude",
    "thinking": "high",
    "tagging": "mention"
  },
  "routines": [
    {
      "name": "Digest for ",
      "prompt": "Summarize [ask: your company] news.",
      "schedule": {
        "kind": "every",
        "everyMs": 3600000
      }
    }
  ],
  "triggers": [
    {
      "name": "Reviews",
      "filter": {
        "prLinks": true,
        "match": {
          "field": "fields.channel",
          "op": "equals",
          "value": "C0ACME"
        }
      },
      "prompt": "Review it for [ask: your company].",
      "cooldownSeconds": 300,
      "delivery": "steer"
    }
  ],
  "disabledTools": [
    "bash"
  ],
  "disabledSkills": [],
  "skills": [
    "review"
  ],
  "open": [
    {
      "kind": "ask",
      "where": "SOUL.md",
      "question": "Where do you work?"
    },
    {
      "kind": "confirm",
      "where": "SOUL.md",
      "question": "Keep this as it is: “prod-eu-1”?",
      "excerpt": "prod-eu-1"
    },
    {
      "kind": "confirm",
      "where": "Skill review: run.sh",
      "question": "Run this script?"
    }
  ],
  "needs": [
    "A GitHub token for [ask: your company].",
    "Slack access."
  ]
}

